:root {
  --bg: #1b1f2a;
  --card: #252b3b;
  --fg: #eef2ff;
  --accent: #7cf5c8;
  --accent-dark: #3dd6a3;
  --muted: #9aa3b8;
  --danger: #ff7a7a;
  --border: #3a4258;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  min-height: 100%;
}

body {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 16px;
  color: var(--fg);
  background-color: var(--bg);
  background-image:
    linear-gradient(45deg, rgba(255,255,255,0.03) 25%, transparent 25%, transparent 75%, rgba(255,255,255,0.03) 75%),
    linear-gradient(45deg, rgba(255,255,255,0.03) 25%, transparent 25%, transparent 75%, rgba(255,255,255,0.03) 75%);
  background-size: 24px 24px;
  background-position: 0 0, 12px 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
}

.card {
  width: 100%;
  max-width: 480px;
  background: var(--card);
  border: 2px solid var(--border);
  border-radius: 12px;
  padding: 24px;
  box-shadow: 0 12px 32px rgba(0,0,0,0.45);
}

.title {
  margin: 0 0 20px;
  font-size: 20px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  text-align: center;
}

.display {
  font-variant-numeric: tabular-nums;
  font-size: clamp(40px, 14vw, 56px);
  line-height: 1.1;
  text-align: center;
  padding: 16px 8px;
  margin-bottom: 20px;
  background: #141824;
  border: 2px solid var(--border);
  border-radius: 8px;
  color: var(--accent);
  letter-spacing: 1px;
  overflow: hidden;
}

.controls {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin-bottom: 24px;
}

.btn {
  font-family: inherit;
  font-size: 16px;
  font-weight: 700;
  padding: 14px 8px;
  border-radius: 8px;
  border: 2px solid var(--border);
  background: #303850;
  color: var(--fg);
  cursor: pointer;
  transition: background 0.15s, transform 0.05s, border-color 0.15s;
}

.btn:hover:not(:disabled) {
  background: #3b4562;
  border-color: var(--accent);
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.btn:active:not(:disabled) {
  transform: translateY(1px);
  background: #283048;
}

.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.btn-primary {
  background: var(--accent);
  color: #10221c;
  border-color: var(--accent-dark);
}

.btn-primary:hover:not(:disabled) {
  background: var(--accent-dark);
  border-color: var(--accent);
}

.btn-primary:active:not(:disabled) {
  background: #2fb98c;
}

.laps {
  border-top: 2px solid var(--border);
  padding-top: 16px;
}

.laps-title {
  margin: 0 0 12px;
  font-size: 16px;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--muted);
}

.lap-list {
  list-style: none;
  margin: 0;
  padding: 0;
  max-height: 220px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.lap-list li {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  background: #1c2231;
  border: 1px solid var(--border);
  border-radius: 6px;
  font-variant-numeric: tabular-nums;
}

.lap-index {
  color: var(--muted);
  font-weight: 700;
}

.lap-time {
  color: var(--accent);
  font-weight: 700;
}

.empty {
  margin: 0;
  color: var(--muted);
  font-size: 16px;
}

.empty.hidden { display: none; }

@media (max-width: 400px) {
  .card { padding: 18px; }
  .controls { gap: 8px; }
  .btn { padding: 12px 4px; }
}

(function () {
  'use strict';

  var display = document.getElementById('display');
  var startStopBtn = document.getElementById('startStop');
  var lapBtn = document.getElementById('lap');
  var resetBtn = document.getElementById('reset');
  var lapList = document.getElementById('lapList');
  var emptyLaps = document.getElementById('emptyLaps');

  var running = false;
  var startTime = 0;
  var elapsed = 0;
  var rafId = null;
  var laps = [];

  function pad(n, len) {
    var s = String(n);
    while (s.length < len) s = '0' + s;
    return s;
  }

  function format(ms) {
    if (ms < 0) ms = 0;
    var totalCs = Math.floor(ms / 10);
    var cs = totalCs % 100;
    var totalSec = Math.floor(totalCs / 100);
    var sec = totalSec % 60;
    var min = Math.floor(totalSec / 60);
    return pad(min, 2) + ':' + pad(sec, 2) + '.' + pad(cs, 2);
  }

  function currentElapsed() {
    return running ? elapsed + (performance.now() - startTime) : elapsed;
  }

  function render() {
    display.textContent = format(currentElapsed());
  }

  function tick() {
    if (!running) return;
    render();
    rafId = requestAnimationFrame(tick);
  }

  function start() {
    if (running) return;
    running = true;
    startTime = performance.now();
    startStopBtn.textContent = 'Stop';
    startStopBtn.setAttribute('aria-label', 'Stop stopwatch');
    lapBtn.disabled = false;
    resetBtn.disabled = false;
    rafId = requestAnimationFrame(tick);
  }

  function stop() {
    if (!running) return;
    elapsed = currentElapsed();
    running = false;
    if (rafId !== null) {
      cancelAnimationFrame(rafId);
      rafId = null;
    }
    startStopBtn.textContent = 'Start';
    startStopBtn.setAttribute('aria-label', 'Start stopwatch');
    render();
  }

  function toggle() {
    if (running) stop(); else start();
  }

  function addLap() {
    if (!running) return;
    var total = currentElapsed();
    var previous = laps.length ? laps[laps.length - 1].total : 0;
    var split = total - previous;
    laps.push({ total: total, split: split });
    renderLaps();
  }

  function renderLaps() {
    lapList.textContent = '';
    if (!laps.length) {
      emptyLaps.classList.remove('hidden');
      return;
    }
    emptyLaps.classList.add('hidden');
    for (var i = laps.length - 1; i >= 0; i--) {
      var lap = laps[i];
      var li = document.createElement('li');

      var indexSpan = document.createElement('span');
      indexSpan.className = 'lap-index';
      indexSpan.textContent = 'Lap ' + (i + 1);

      var timeSpan = document.createElement('span');
      timeSpan.className = 'lap-time';
      timeSpan.textContent = format(lap.split);
      timeSpan.title = 'Total ' + format(lap.total);

      li.appendChild(indexSpan);
      li.appendChild(timeSpan);
      lapList.appendChild(li);
    }
  }

  function reset() {
    if (rafId !== null) {
      cancelAnimationFrame(rafId);
      rafId = null;
    }
    running = false;
    elapsed = 0;
    laps = [];
    startStopBtn.textContent = 'Start';
    startStopBtn.setAttribute('aria-label', 'Start stopwatch');
    lapBtn.disabled = true;
    resetBtn.disabled = true;
    render();
    renderLaps();
  }

  startStopBtn.addEventListener('click', toggle);
  lapBtn.addEventListener('click', addLap);
  resetBtn.addEventListener('click', reset);

  render();
  renderLaps();
})();
